import { expect, test, type Page } from '@playwright/test'

// A 400x300 PNG generated by a canvas in the page (a user action in the page's
// own world), so the test makes no network request and mutates no page or
// storage state beyond that canvas.
async function png400x300(page: Page): Promise<Buffer> {
  const buf = await page.evaluate(async () => {
    const canvas = document.createElement('canvas')
    canvas.width = 400
    canvas.height = 300
    const ctx = canvas.getContext('2d')!
    ctx.fillStyle = '#123456'
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = '#ABCDEF'
    ctx.fillRect(0, 0, 200, 150)
    ctx.fillStyle = '#00FF00'
    ctx.fillRect(200, 150, 200, 150)
    const blob: Blob = await new Promise((resolve, reject) =>
      canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('toBlob failed'))), 'image/png'),
    )
    return Array.from(new Uint8Array(await blob.arrayBuffer()))
  })
  return Buffer.from(buf)
}

async function loadTestPng(page: Page) {
  const [chooser] = await Promise.all([
    page.waitForEvent('filechooser'),
    page.getByRole('button', { name: 'Load image' }).click(),
  ])
  await chooser.setFiles({ name: 'test.png', mimeType: 'image/png', buffer: await png400x300(page) })
}

const dims = (page: Page) => page.getByText(/\d+ x \d+ px/)

test('[A1] with no image loaded the page shows the heading, the no-image text and the Load image button', async ({ page }) => {
  await page.goto('/')
  await expect(page.getByRole('heading', { name: 'Image Cropper' })).toBeVisible()
  await expect(page.getByText('No image loaded')).toBeVisible()
  await expect(page.getByRole('button', { name: 'Load image' })).toBeVisible()
})

test('[A2] loading a 400x300 PNG shows the image and the dimensions label 400 x 300 px', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  await expect(dims(page)).toHaveText('400 x 300 px')
  const canvas = page.locator('canvas').first()
  await expect(canvas).toBeVisible()
  expect(await canvas.count()).toBeGreaterThan(0)
})

test('[A3] dragging the bottom-right crop handle and applying the crop resizes the canvas to 200 x 150 px', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  const canvas = page.locator('canvas').first()
  const box = await canvas.boundingBox()
  if (!box) throw new Error('no canvas box')
  // A 200x150 crop is the bottom-right quarter of the 400x300 source, so the
  // bottom-right handle must end at the middle of the canvas display box.
  // The crop starts full-size (handle at the canvas corner); the spec says
  // "dragging the handle ... to create" the region, so the drag begins there.
  const target = { x: box.x + box.width / 2, y: box.y + box.height / 2 }
  await page.mouse.move(box.x + box.width, box.y + box.height)
  await page.mouse.down()
  await page.mouse.move(target.x, target.y, { steps: 10 })
  await page.mouse.up()
  await page.getByRole('button', { name: 'Apply crop' }).click()
  await expect(dims(page)).toHaveText('200 x 150 px')
})

test('[A4] resizing with width 100 and height 75 updates the dimensions label to 100 x 75 px', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  await page.getByLabel('Width').fill('100')
  await page.getByLabel('Height').fill('75')
  await page.getByRole('button', { name: 'Resize' }).click()
  await expect(dims(page)).toHaveText('100 x 75 px')
})

test('[A5] rotating 90 degrees swaps the dimensions to 300 x 400 px', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  await page.getByRole('button', { name: 'Rotate 90' }).click()
  await expect(dims(page)).toHaveText('300 x 400 px')
})

test('[A6] flipping horizontal keeps the dimensions at 400 x 300 px but mirrors the image content', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  const canvas = page.locator('canvas').first()
  const before = await canvas.screenshot()
  await page.getByRole('button', { name: 'Flip horizontal' }).click()
  await expect(dims(page)).toHaveText('400 x 300 px')
  const after = await canvas.screenshot()
  expect(after).not.toEqual(before)
})

test('[A7] selecting Grayscale applies the filter and the select shows Grayscale', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  const canvas = page.locator('canvas').first()
  const before = await canvas.screenshot()
  const filter = page.getByLabel('Filter')
  await filter.selectOption({ label: 'Grayscale' })
  await expect(filter).toHaveValue('Grayscale')
  const after = await canvas.screenshot()
  expect(after).not.toEqual(before)
})

test('[A8] exporting PNG triggers a download of a file named cropped.png', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.getByRole('button', { name: 'Export PNG' }).click(),
  ])
  expect(download.suggestedFilename()).toBe('cropped.png')
})

test('[A9] reload keeps the loaded image and its dimensions', async ({ page }) => {
  await page.goto('/')
  await loadTestPng(page)
  await expect(dims(page)).toHaveText('400 x 300 px')
  await page.reload()
  await expect(dims(page)).toHaveText('400 x 300 px')
  const canvas = page.locator('canvas').first()
  await expect(canvas).toBeVisible()
})
